css:
[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
[data-chat-canvas]{background-image:radial-gradient(ellipse 60% 38% at 50% 0%,rgba(200,68,47,.09),transparent 70%),repeating-linear-gradient(0deg,rgba(90,60,30,.06) 0 1px,transparent 1px 30px)!important}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;letter-spacing:-.01em}
[data-user-message-bubble]{box-shadow:inset 0 0 0 1px rgba(120,80,40,.16)}
[data-slot="composer-host"]{box-shadow:0 1px 0 rgba(120,80,40,.08),0 8px 24px -14px rgba(120,60,30,.35)}
::selection{background:rgba(200,68,47,.22)}
